import {getActiveWorld} from '../image-generation/world.js';
import {TEXT_MODELS} from './models.js';
import {saveCredential,removeCredential,hasCredential} from '../image-generation/vault.js';
const ENGINES=['openai','anthropic','google','local'],clone=x=>JSON.parse(JSON.stringify(x));
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let api,configured=false;
export function getTextGenerationSettings(state){
 const source=state.settings?.textGeneration||{},engine=ENGINES.includes(source.engine)?source.engine:'openai',providers={};
 for(const id of ENGINES){const p=source.providers?.[id]||{};providers[id]={model:id==='local'?String(p.model||''):TEXT_MODELS[id].id,...(id==='local'?{baseUrl:p.baseUrl||'http://127.0.0.1:1234/v1'}:{}),...(p.proxyEndpoint?{proxyEndpoint:p.proxyEndpoint,transport:'proxy'}:{})};}
 return {engine,providers,hybrid:{enabled:source.hybrid?.enabled===true,finalEngine:ENGINES.slice(0,3).includes(source.hybrid?.finalEngine)?source.hybrid.finalEngine:'openai'}};
}
function options(selected,local=true){return ENGINES.filter(id=>local||id!=='local').map(id=>`<option value="${id}" ${id===selected?'selected':''}>${esc(TEXT_MODELS[id].name)}</option>`).join('');}
function providerFields(settings,engine){const p=settings.providers[engine];if(engine==='local')return `<div class="form-grid"><div class="field"><label for="tg-base-url">OpenAI 호환 로컬 주소</label><input id="tg-base-url" type="url" value="${esc(p.baseUrl)}" placeholder="http://127.0.0.1:1234/v1"><small>LM Studio·Ollama에서 모델과 서버를 실행해 주세요. 주소는 /v1까지 입력합니다.</small></div><div class="field"><label for="tg-local-model">로컬 모델 이름 · 선택</label><input id="tg-local-model" maxlength="200" value="${esc(p.model)}" placeholder="비우면 /v1/models의 첫 실행 모델"><small>API 요금은 없으며 컴퓨터 비용은 별도예요.</small></div></div>`;
 let saved=false;try{saved=hasCredential(engine);}catch{}
 return `<p class="small-label">모델 ${esc(p.model)} · 입력 $${TEXT_MODELS[engine].input} / 출력 $${TEXT_MODELS[engine].output} (100만 토큰 · 참고 단가)</p><div class="field"><label for="tg-api-key">${esc(engine)} API 비밀 키</label><input id="tg-api-key" type="password" autocomplete="off" maxlength="16384" placeholder="${saved?'이미지·글 엔진이 같은 저장된 키를 공유해요 · 교체 시 입력':'비밀 키 전체를 입력하세요'}"><small>${engine==='openai'?'key_ 추적 ID나 sk-… 가려진 값이 아니라 생성할 때 복사한 sk- 비밀 키 전체입니다. ':' '}PIN에서 파생한 키로 기기에 암호화해 보관하며 백업에 넣지 않습니다.</small></div><div class="material-add-actions"><button type="button" class="btn btn-outline" data-text-setting="save-key">키 암호화 저장</button><button type="button" class="btn btn-outline" data-text-setting="delete-key">저장된 키 삭제</button></div><div class="field" style="margin-top:15px"><label for="tg-proxy">글 프록시 주소 · 선택</label><input id="tg-proxy" type="url" value="${esc(p.proxyEndpoint||'')}" placeholder="https://my-proxy.example"><small>프록시는 서버 환경변수 키를 사용합니다. 브라우저의 키를 보내지 않아요.</small></div>`;
}
export function renderTextSettings(state){const settings=getTextGenerationSettings(state);return `<section class="panel" id="text-engine-settings" style="margin:24px 0"><h3>이야기 글 엔진 · 이미지 엔진과 별도</h3><p class="section-sub">줄거리 → 한글·영어 전문 → 쪽 나누기를 이 엔진으로 작성합니다. 아래 World의 그림 엔진은 그대로 별도 설정해요.</p><form id="text-engine-form"><div class="field"><label for="tg-engine">이야기 생성 엔진</label><select id="tg-engine">${options(settings.engine)}</select></div><div id="tg-provider-fields">${providerFields(settings,settings.engine)}</div><div class="field" style="margin-top:18px"><label><input id="tg-hybrid" type="checkbox" ${settings.hybrid.enabled?'checked':''}> 하이브리드 · 로컬로 줄거리·초안을 만들고 API로 전문 다듬기</label><small>로컬 설정의 주소·모델을 먼저 저장하세요. API로 다듬은 전문을 승인한 뒤 쪽 나누기도 최종 글 엔진으로 실행합니다.</small></div><div class="field"><label for="tg-final-engine">하이브리드 최종 글 엔진</label><select id="tg-final-engine">${options(settings.hybrid.finalEngine,false)}</select><small>최종 엔진의 API 키도 해당 엔진을 선택해서 저장해 주세요.</small></div><p id="tg-error" class="pin-error" role="status" aria-live="polite"></p><div class="modal-actions"><button class="btn btn-green" type="submit">글 엔진 설정 저장</button></div></form></section>`;}
function checkedUrl(raw){if(!raw)return '';const url=new URL(raw);if(!['http:','https:'].includes(url.protocol)||url.username||url.password||url.search||url.hash)throw new Error('주소에는 HTTP(S) 주소만 입력해 주세요.');return url.href.replace(/\/+$/,'');}
function showError(error){const el=document.querySelector('#tg-error');if(el)el.textContent=error.message;api.toast(error.message);}
export function configureTextSettingsUI(context){api=context;if(configured)return;configured=true;
 document.addEventListener('change',event=>{if(event.target.id==='tg-engine'&&api.isParent())document.querySelector('#tg-provider-fields').innerHTML=providerFields(getTextGenerationSettings(api.getState()),event.target.value);});
 document.addEventListener('click',event=>{const button=event.target.closest('[data-text-setting]');if(!button)return;event.preventDefault();api.protectedAction(async()=>{try{const engine=document.querySelector('#tg-engine').value,field=document.querySelector('#tg-api-key');if(button.dataset.textSetting==='save-key'){await saveCredential(engine,field.value);if(field.isConnected)field.value='';api.toast('글·이미지에서 공유할 키를 암호화해 저장했어요.');}else{await removeCredential(engine);if(field)field.value='';api.toast('이 공급자의 공유 키를 삭제했어요.');}const error=document.querySelector('#tg-error');if(error)error.textContent='';}catch(error){showError(error);}});});
 document.addEventListener('submit',event=>{if(event.target.id!=='text-engine-form')return;event.preventDefault();api.protectedAction(()=>{try{const state=api.getState(),settings=getTextGenerationSettings(state),engine=document.querySelector('#tg-engine').value;settings.engine=engine;if(engine==='local'){settings.providers.local.baseUrl=checkedUrl(document.querySelector('#tg-base-url').value);if(!settings.providers.local.baseUrl)throw new Error('로컬 엔드포인트 주소를 입력해 주세요.');settings.providers.local.model=document.querySelector('#tg-local-model').value.trim();}else{const proxy=checkedUrl(document.querySelector('#tg-proxy').value.trim());settings.providers[engine]={model:TEXT_MODELS[engine].id,...(proxy?{proxyEndpoint:proxy,transport:'proxy'}:{})};}settings.hybrid={enabled:document.querySelector('#tg-hybrid').checked,finalEngine:document.querySelector('#tg-final-engine').value};state.settings.textGeneration=clone(settings);getActiveWorld(state).textGeneration=clone(settings);if(api.save()){api.render();api.toast('이야기 글 엔진을 저장했어요. 이미지 엔진은 별도로 유지됩니다.');}}catch(error){showError(error);}});});
}
